export class AMF {
    static parse(data: any): {} | undefined;
    static _parseValue(view: any): {
        data: any;
        size: number;
        isEnd: boolean;
    };
    static _parseString(view: any): {
        data: string;
        size: any;
    };
    static _parseObject(view: any): {
        data: {
            name: string;
            value: any;
        };
        size: any;
        isEnd: any;
    } | undefined;
}
